def wait_ssh(host, u='deploy', k=None, name=None, p=22, tout=300, interval=5, key_pass=None, password=None, verbose=True):
    'Retry an SSH connection to `host` until it works, raising TimeoutError after `tout` seconds.'
    dl = time.time() + tout
    key_pass, password = _resolve_cred(key_pass, password)
    while time.time() < dl:
        try:
            run_ssh(host, 'true', user=u, key=k, name=name, port=p, key_pass=key_pass, password=password)
            if verbose: print(f'SSH to host {host} check succeeded')
            return True
        except Exception as e:
            if verbose: print(f'SSH to {host} not ready yet, retrying in {interval}s).Error:{e}')
            time.sleep(interval)
    raise TimeoutError(f'SSH to {host} not ready after {tout}s')

def chk_cloud_init(host, u='deploy', k=None, name=None, key_pass=None, password=None, verbose=True, port=22) -> str:
    'Return `done`, `running` or `error` for the setup of `host`, read from the cloud-init or `cloud_init_sh` marker files.'
    c = ("if [ -f /var/lib/vpseasy/error ]; then echo 'status: error'; "
         "elif [ -d /var/lib/vpseasy ]; then { test -f /var/lib/vpseasy/ready && echo 'status: done' || echo 'status: running'; }; "
         "else { test -f /var/lib/cloud/instance/boot-finished && echo 'status: done' || echo 'status: running'; }; fi")
    key_pass, password = _resolve_cred(key_pass, password)
    o = run_ssh(host, c, user=u, key=k, name=name, port=port, key_pass=key_pass, password=password, check=False, verbose=verbose)
    o = o[1].strip()
    return o.split(': ', 1)[-1].strip() if ': ' in o else (o or 'unknown')


# %% ../nbs/00_core.ipynb #0d506066
def wait_ready(host,
               u='deploy',
               k=None,
               name=None,
               tout=300,
               interval=5,
               retries=2,
               key_pass=None,
               password=None,
               verbose=False,
               port=22
):
    'Wait until SSH answers on `host`, then until cloud-init reports done, giving slow setups `retries` extra rounds.'
    key_pass, password = _resolve_cred(key_pass, password)
    wait_ssh(host,u=u,k=k,name=name,p=port,tout=tout,interval=interval,key_pass=key_pass,password=password,verbose=verbose)
    for a in range(retries + 1):
        dl = time.time() + tout
        while time.time() < dl:
            status = chk_cloud_init(host, u=u, k=k, name=name, key_pass=key_pass, password=password, port=port)
            if verbose: print(f'cloud-init status: {status}')
            if status == 'done': return True
            if status == 'error': raise RuntimeError(f'cloud-init failed on {host}')
            time.sleep(interval)
        if a < retries: print(f'cloud-init on {host} still running after {tout}s — retrying ({a+1}/{retries}) ...')
    raise TimeoutError(f'cloud-init on {host} not done after {tout * (retries + 1)}s ({retries + 1} attempts)')

