def vols_to_binds(vols):
    'Turn container paths such as `/app/data` into Compose bind mounts such as `./data:/app/data`.'
    return [f'./{v.split("/")[-1]}:{v}' for v in listify(vols)]

def _svc(d, kw):
    'Merge `kw` into service dict `d`, appending its `volumes` to the existing ones.'
    kw = dict(kw or {}); vs = kw.pop('volumes', None)
    return d | kw | ({'volumes': [*(d.get('volumes') or []), *listify(vs)]} if vs else {})

def caddy_stack(domain, df, vols=None, env_file='.env', cloudflared=True, root=None, conf=None, litestream=None,
                app_kw=None, caddy_kw=None, cloudflared_kw=None, caddyfile=None, write_caddyfile=True, **kw):
    'Build a Compose file with the app, Caddy, and optionally cloudflared and Litestream, saving it with its Dockerfile and Caddyfile in `root`.'
    root = Path(root if root else '.')
    df.save(Path(root)/'Dockerfile')
    v,env = vols_to_binds(vols) if vols else None, listify(env_file) if env_file else None
    dbs = listify(litestream['dbs']) if litestream else []
    rs = [_restore_name(p, len(dbs)) for p in dbs]
    app = dict(build=df, volumes=v, env_file=env, restart='unless-stopped', networks=['web'],
               depends_on={r: dict(condition='service_completed_successfully') for r in rs} or None)
    cdy = caddy_svc(domain, cloudflared=cloudflared, conf=conf or root/'Caddyfile', caddyfile=caddyfile, save=write_caddyfile,
                    mount=None if conf else './Caddyfile', **kw)
    c = Compose().svc('app', **_svc(app, app_kw)).svc('caddy', **_svc(cdy, caddy_kw))
    if cloudflared: c = c.svc('cloudflared', **_svc(cloudflared_svc(url='http://caddy'), cloudflared_kw))
    if litestream:
        litestream_conf(conf=root/'litestream.yml', vols=listify(vols), **litestream)
        lv = [o for o in listify(vols) if any(_under(p, o) for p in listify(litestream['dbs']))]
        for r,p in zip(rs, dbs):
            c = c.svc(r, **litestream_svc(vols=lv, env_file=env_file, cmd=f'restore -if-db-not-exists -if-replica-exists {p}', restart='no'))
        c = c.svc('litestream', **litestream_svc(vols=lv, env_file=env_file, depends_on=['app']))
    c = c.network('web').volume('caddy_data').volume('caddy_config')
    if root: c.save(root/'docker-compose.yml')
    return c


